      "expected_slip_edition": "《護國嘉濟江東王靈籤》（傅燁撰，道藏本）",
      "field": "聖意",
      "text": "訟與病，險而平，名與利，迍而亨，婚先難，終必成，行人至，福自生。",
      "display_selection": null,
      "status": "PROBABLE",
      "confirmed": false,
      "source": "護國嘉濟江東王靈籤（傅燁撰，道藏本／維基文庫 transcription）",
