      "field": "聖意",
      "text": "財物聚，病即愈，若問訟，必遇主，更修善，禱神助，行人回，事無阻。",
      "display_selection": null,
      "status": "PROBABLE",
      "confirmed": false,
      "source": "護國嘉濟江東王靈籤（傅燁撰，道藏本／維基文庫 transcription）",
