      "field": "聖意",
      "text": "問公訟，且審理，求財祿，當揣己，病早禳，宜求嗣，婚更審，方吉利。",
      "display_selection": null,
      "status": "PROBABLE",
      "confirmed": false,
      "source": "護國嘉濟江東王靈籤（傅燁撰，道藏本／維基文庫 transcription）",
