      "field": "聖意",
      "text": "訟宜解，莫信讒，財緩取，名莫責，孕較遲，行人遠，婚更審，莫妄攀。",
      "display_selection": null,
      "status": "PROBABLE",
      "confirmed": false,
      "source": "護國嘉濟江東王靈籤（傅燁撰，道藏本／維基文庫 transcription）",
