      "field": "聖意",
      "text": "名利無，病有祟，訟莫興，和為貴，莫責財，婚不利，孕無憂，行未至。",
      "display_selection": null,
      "status": "PROBABLE",
      "confirmed": false,
      "source": "護國嘉濟江東王靈籤（傅燁撰，道藏本／維基文庫 transcription）",
