      "field": "聖意",
      "text": "財聚散，病反覆，欲求安，候三伏。事進退，宜作福，婚可成，審往復。",
      "display_selection": null,
      "status": "PROBABLE",
      "confirmed": false,
      "source": "護國嘉濟江東王靈籤（傅燁撰，道藏本／維基文庫 transcription）",
