      "field": "聖意",
      "text": "遇貴人，訟得理，財尚遲，病未愈，婚未成，信尚阻，待秋冬，方有遇。",
      "display_selection": null,
      "status": "PROBABLE",
      "confirmed": false,
      "source": "護國嘉濟江東王靈籤（傅燁撰，道藏本／維基文庫 transcription）",
