      "corpus_id": "liushijiazi",
      "slip_number": 3,
      "expected_slip_edition": "北港朝天宮官方六十甲子籤（modern reference edition）",
      "field": "聖意",
      "text": "討海：晚有大成\n作塭：利者必得\n魚苗：後得大利\n求財：和財則多\n耕作：下冬好\n經商：後先大利\n月令：潮潮得春\n六畜：可納\n透信：音守難逢\n尋人：得回\n失物：在月光\n家宅：得和稍破\n婚姻：可成\n移居：徙吉\n六甲：生男\n病篤：大吉\n作事：二次成\n功名：發科甲有進\n官事：從寬不究\n年冬：八分\n求嗣：有過目\n治療：平安不吉",
