      "notes": "legacy OCR（Study 03）聖意層：討海晚有大成／作塭利者必得／魚苗後得大利",
      "source_hash": "afef598d3ae2b818b50c803bbb2075e5ac92bddc2a32645d5daf2ce35fc723dd"
