      "expected_slip_edition": "北港朝天宮官方六十甲子籤（modern reference edition）",
      "field": "聖意",
      "text": "訂婚 有大財\n作場 有望\n魚苗 月光好\n求財 在外家好\n出家 另計\n耕作 有收\n經商 大吉利\n月令 好\n六甲 先生 無\n疾病 門庭 作事 必成\n女胎 可成 移居 可應 功名 宗耀祖\n婚姻 可成 墳墓 可得 官事 貴人財\n家運 平安 填墓 可得 失物 月光在\n失物 月光在 出外 求財好 家事 難辦\n行人 快遇 行舟 大吉 求兒 好\n送信 運到 凡事 吉或大 求雨 到月好\n六畜 無 治病 應近日 年冬 允收",
