      "field": "聖意",
      "text": "許海 輕邪後先\n作媽 得先難後\n六甲 男產生\n婚姻 多口舌\n移居 不可\n功名 緩必遲\n求財 以時待\n失物 難尋在\n出外 下半年\n行舟 風波見有\n疾病 禳送平安\n家宅 有貴人\n國運 平正\n官事 被官莫興\n墓墳 先拜後\n魚苗 無儀\n家道 先祥\n求兒 空望\n耕作 想空\n經商 遇先貴人\n納妾 貴利\n月令 淡淡\n六畜 不戒\n治病 暗月无吉\n年冬 平正",
