      "field": "聖意",
      "text": "對海 費了工\n作強 了貢本\n魚苗蚶 本\n求財 不多\n失物 難尋不出\n耕作 大不好\n看人 慢明待暗\n經商 了債成己\n月令 不吉運\n這信 望正得\n六甲 先育後\n六畜 利了三魚\n紊室 慢不可且\n家運 吉无後\n移居 慢不成\n婚姻 不成\n填墓 占地勝\n官事 難了大成\n治病 屬不拖\n出外 無貴人\n行舟 得利盈\n家事 逢屋多口\n求兒 不可\n凡事 無貴人謀\n功名 費了工夫\n作事 難成\n行人 未來\n求雨 未有\n貴人 生中若不沒我正是願心",
